    public List<PricingPackage> pricingPackages(){String sql="SELECT PRICING_PACKAGE_ID,PACKAGE_CODE,PACKAGE_NAME,EFFECTIVE_FROM,EFFECTIVE_TO,STATUS_CODE FROM "+schema+".DEPOSIT_PRICING_PACKAGE WHERE STATUS_CODE='ACTIVE' AND EFFECTIVE_FROM<=TRUNC(SYSDATE) AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=TRUNC(SYSDATE)) ORDER BY PRICING_PACKAGE_ID DESC";return jdbc.query(sql,Map.of(),(r,n)->new PricingPackage(r.getLong(1),r.getString(2),r.getString(3),date(r.getDate(4)),date(r.getDate(5)),r.getString(6)));}
    public List<PricingPackageBenefit> packageBenefits(){String sql="SELECT B.PACKAGE_BENEFIT_ID,B.PRICING_PACKAGE_ID,B.BENEFIT_TYPE_CODE,B.TARGET_CODE,B.BENEFIT_VALUE,B.MAX_BENEFIT_AMOUNT FROM "+schema+".DEPOSIT_PRICING_PACKAGE_BENEFIT B JOIN "+schema+".DEPOSIT_PRICING_PACKAGE P ON P.PRICING_PACKAGE_ID=B.PRICING_PACKAGE_ID WHERE P.STATUS_CODE='ACTIVE' ORDER BY B.PRICING_PACKAGE_ID,B.PACKAGE_BENEFIT_ID";return jdbc.query(sql,Map.of(),(r,n)->new PricingPackageBenefit(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6)));}
