    public List<TaxAdjustment> taxAdjustments(long accountId){String sql="SELECT J.TAX_ADJUSTMENT_ID,J.TAX_CALCULATION_ID,J.ADJUSTMENT_TYPE_CODE,J.ADJUSTMENT_AMOUNT,J.REASON_CODE,J.EFFECTIVE_DATE,J.APPROVAL_REQUEST_ID,A.APPROVAL_STATUS_CODE,J.POSTING_REFERENCE FROM "+schema+".DEPOSIT_TAX_ADJUSTMENT J JOIN "+schema+".DEPOSIT_TAX_CALCULATION C ON C.TAX_CALCULATION_ID=J.TAX_CALCULATION_ID LEFT JOIN "+schema+".DEPOSIT_OPERATION_APPROVAL_REQUEST A ON A.APPROVAL_REQUEST_ID=J.APPROVAL_REQUEST_ID WHERE C.ACCOUNT_ID=:id ORDER BY J.TAX_ADJUSTMENT_ID DESC";return jdbc.query(sql,Map.of("id",accountId),(r,n)->new TaxAdjustment(r.getLong(1),r.getLong(2),r.getString(3),r.getBigDecimal(4),r.getString(5),date(r.getDate(6)),r.getObject(7,Long.class),r.getString(8),r.getString(9)));}
    public List<TaxLiability> taxLiabilities(long accountId){String sql="SELECT DISTINCT L.TAX_LIABILITY_ID,L.JURISDICTION_CODE,L.TAX_TYPE_CODE,L.PERIOD_START,L.PERIOD_END,L.LIABILITY_AMOUNT,L.PAID_AMOUNT,L.STATUS_CODE FROM "+schema+".DEPOSIT_TAX_LIABILITY L JOIN "+schema+".DEPOSIT_TAX_RULE R ON R.TAX_TYPE_CODE=L.TAX_TYPE_CODE JOIN "+schema+".DEPOSIT_TAX_CALCULATION C ON C.TAX_RULE_ID=R.TAX_RULE_ID WHERE C.ACCOUNT_ID=:id ORDER BY L.PERIOD_END DESC,L.TAX_LIABILITY_ID DESC";return jdbc.query(sql,Map.of("id",accountId),(r,n)->new TaxLiability(r.getLong(1),r.getString(2),r.getString(3),date(r.getDate(4)),date(r.getDate(5)),r.getBigDecimal(6),r.getBigDecimal(7),r.getString(8)));}
    public List<TaxPayment> taxPayments(long accountId){String sql="SELECT DISTINCT P.TAX_PAYMENT_ID,P.TAX_LIABILITY_ID,P.PAYMENT_AMOUNT,P.PAYMENT_DATE,P.PAYMENT_STATUS_CODE,P.PAYMENT_REFERENCE FROM "+schema+".DEPOSIT_TAX_PAYMENT P JOIN "+schema+".DEPOSIT_TAX_LIABILITY L ON L.TAX_LIABILITY_ID=P.TAX_LIABILITY_ID JOIN "+schema+".DEPOSIT_TAX_RULE R ON R.TAX_TYPE_CODE=L.TAX_TYPE_CODE JOIN "+schema+".DEPOSIT_TAX_CALCULATION C ON C.TAX_RULE_ID=R.TAX_RULE_ID WHERE C.ACCOUNT_ID=:id ORDER BY P.TAX_PAYMENT_ID DESC";return jdbc.query(sql,Map.of("id",accountId),(r,n)->new TaxPayment(r.getLong(1),r.getLong(2),r.getBigDecimal(3),date(r.getDate(4)),r.getString(5),r.getString(6)));}
    public List<TaxReconciliation> taxReconciliations(long accountId){String sql="SELECT DISTINCT X.TAX_RECONCILIATION_ID,X.BUSINESS_DATE,X.TAX_TYPE_CODE,X.BOOK_AMOUNT,X.REMITTED_AMOUNT,X.EXTERNAL_AMOUNT,X.DIFFERENCE_AMOUNT,X.STATUS_CODE,X.RESOLUTION_REFERENCE FROM "+schema+".DEPOSIT_TAX_RECONCILIATION X JOIN "+schema+".DEPOSIT_TAX_RULE R ON R.TAX_TYPE_CODE=X.TAX_TYPE_CODE JOIN "+schema+".DEPOSIT_TAX_CALCULATION C ON C.TAX_RULE_ID=R.TAX_RULE_ID WHERE C.ACCOUNT_ID=:id ORDER BY X.BUSINESS_DATE DESC,X.TAX_RECONCILIATION_ID DESC";return jdbc.query(sql,Map.of("id",accountId),(r,n)->new TaxReconciliation(r.getLong(1),date(r.getDate(2)),r.getString(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getString(8),r.getString(9)));}

