    public void insertFeeRule(long id,long productVersionId,String feeCode,String eventCode,String method,BigDecimal fixed,BigDecimal rate,BigDecimal min,BigDecimal max,long version,LocalDate from,LocalDate to,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_FEE_RULE(FEE_RULE_ID,PRODUCT_VERSION_ID,FEE_CODE,FEE_EVENT_CODE,CALCULATION_METHOD_CODE,FIXED_AMOUNT,RATE_VALUE,MIN_FEE_AMOUNT,MAX_FEE_AMOUNT,RULE_VERSION_NO,EFFECTIVE_FROM,EFFECTIVE_TO,IS_ACTIVE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:pvid,:code,:event,:method,:fixed,:rate,:min,:max,:ver,:vf,:vt,1,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("pvid",productVersionId).addValue("code",feeCode).addValue("event",eventCode).addValue("method",method).addValue("fixed",fixed).addValue("rate",rate).addValue("min",min).addValue("max",max).addValue("ver",version).addValue("vf",Date.valueOf(from)).addValue("vt",to==null?null:Date.valueOf(to),Types.DATE).addValue("actor",actor));}
    public void insertFeeTier(long id,long feeRuleId,long tierNo,BigDecimal min,BigDecimal max,BigDecimal amount,BigDecimal rate,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_FEE_TIER(FEE_TIER_ID,FEE_RULE_ID,TIER_NO,MIN_BASE_AMOUNT,MAX_BASE_AMOUNT,FEE_AMOUNT,FEE_RATE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:rid,:no,:min,:max,:amount,:rate,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("rid",feeRuleId).addValue("no",tierNo).addValue("min",min).addValue("max",max).addValue("amount",amount).addValue("rate",rate).addValue("actor",actor));}
