    public List<FeeTier> feeTiersForRule(long ruleId){String sql="SELECT FEE_TIER_ID,FEE_RULE_ID,TIER_NO,MIN_BASE_AMOUNT,MAX_BASE_AMOUNT,FEE_AMOUNT,FEE_RATE FROM "+schema+".DEPOSIT_FEE_TIER WHERE FEE_RULE_ID=:id ORDER BY TIER_NO";return jdbc.query(sql,Map.of("id",ruleId),(r,n)->new FeeTier(r.getLong(1),r.getLong(2),r.getLong(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7)));}
    public void insertFeeAssessment(long id,long accountId,Long transactionId,long feeRuleId,BigDecimal base,BigDecimal calculated,BigDecimal discount,BigDecimal finalAmount,String collectionMethod,String waiver,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_FEE_ASSESSMENT(FEE_ASSESSMENT_ID,ACCOUNT_ID,TRANSACTION_ID,FEE_RULE_ID,BASE_AMOUNT,CALCULATED_FEE_AMOUNT,DISCOUNT_AMOUNT,FINAL_FEE_AMOUNT,ASSESSMENT_STATUS_CODE,COLLECTION_METHOD_CODE,WAIVER_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:aid,:tx,:rid,:base,:calc,:disc,:final,'CALCULATED',:method,:waiver,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("aid",accountId).addValue("tx",transactionId,Types.NUMERIC).addValue("rid",feeRuleId).addValue("base",base).addValue("calc",calculated).addValue("disc",discount).addValue("final",finalAmount).addValue("method",collectionMethod).addValue("waiver",waiver).addValue("actor",actor));}
    public BigDecimal feeRevenue(long accountId,LocalDate start,LocalDate end){String sql="SELECT NVL(SUM(FINAL_FEE_AMOUNT),0) FROM "+schema+".DEPOSIT_FEE_ASSESSMENT WHERE ACCOUNT_ID=:aid AND CREATED_AT>=:ps AND CREATED_AT<:pe+1";return jdbc.queryForObject(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("ps",Date.valueOf(start)).addValue("pe",Date.valueOf(end)),BigDecimal.class);}
    public BigDecimal interestExpense(long accountId,LocalDate start,LocalDate end){String sql="SELECT NVL(SUM(PAYMENT_AMOUNT),0) FROM "+schema+".DEPOSIT_PROFIT_PAYMENT WHERE ACCOUNT_ID=:aid AND PAYMENT_DATE BETWEEN :ps AND :pe AND PAYMENT_STATUS_CODE='PAID'";return jdbc.queryForObject(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("ps",Date.valueOf(start)).addValue("pe",Date.valueOf(end)),BigDecimal.class);}
    public void insertProfitability(long id,long accountId,Long productVersion,Long partyId,LocalDate start,LocalDate end,BigDecimal avg,BigDecimal interest,BigDecimal fees,BigDecimal other,BigDecimal cost,BigDecimal net,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_PROFITABILITY_SNAPSHOT(PROFITABILITY_SNAPSHOT_ID,ACCOUNT_ID,PRODUCT_VERSION_ID,PARTY_ID,PERIOD_START,PERIOD_END,AVERAGE_BALANCE,INTEREST_EXPENSE,FEE_REVENUE,OTHER_REVENUE,DIRECT_COST,NET_MARGIN,CALCULATED_AT,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:aid,:pvid,:pid,:ps,:pe,:avg,:interest,:fees,:other,:cost,:net,SYSTIMESTAMP,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("aid",accountId).addValue("pvid",productVersion,Types.NUMERIC).addValue("pid",partyId,Types.NUMERIC).addValue("ps",Date.valueOf(start)).addValue("pe",Date.valueOf(end)).addValue("avg",avg).addValue("interest",interest).addValue("fees",fees).addValue("other",other).addValue("cost",cost).addValue("net",net).addValue("actor",actor));}

    public BigDecimal taxBookAmount(long accountId,String taxType,LocalDate start,LocalDate end){String sql="SELECT NVL(SUM(C.TAX_AMOUNT),0)+NVL((SELECT SUM(J.ADJUSTMENT_AMOUNT) FROM "+schema+".DEPOSIT_TAX_ADJUSTMENT J JOIN "+schema+".DEPOSIT_TAX_CALCULATION C2 ON C2.TAX_CALCULATION_ID=J.TAX_CALCULATION_ID JOIN "+schema+".DEPOSIT_TAX_RULE R2 ON R2.TAX_RULE_ID=C2.TAX_RULE_ID LEFT JOIN "+schema+".DEPOSIT_OPERATION_APPROVAL_REQUEST A ON A.APPROVAL_REQUEST_ID=J.APPROVAL_REQUEST_ID WHERE C2.ACCOUNT_ID=:aid AND R2.TAX_TYPE_CODE=:type AND J.EFFECTIVE_DATE BETWEEN :ps AND :pe AND (J.APPROVAL_REQUEST_ID IS NULL OR A.APPROVAL_STATUS_CODE='APPROVED')),0) FROM "+schema+".DEPOSIT_TAX_CALCULATION C JOIN "+schema+".DEPOSIT_TAX_RULE R ON R.TAX_RULE_ID=C.TAX_RULE_ID WHERE C.ACCOUNT_ID=:aid AND R.TAX_TYPE_CODE=:type AND C.CREATED_AT>=:ps AND C.CREATED_AT<:pe+1";return jdbc.queryForObject(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",taxType).addValue("ps",Date.valueOf(start)).addValue("pe",Date.valueOf(end)),BigDecimal.class);}
    public void insertTaxLiability(long id,String jurisdiction,String taxType,LocalDate start,LocalDate end,BigDecimal amount,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_TAX_LIABILITY(TAX_LIABILITY_ID,JURISDICTION_CODE,TAX_TYPE_CODE,PERIOD_START,PERIOD_END,LIABILITY_AMOUNT,PAID_AMOUNT,STATUS_CODE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:jur,:type,:ps,:pe,:amount,0,:status,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("jur",jurisdiction).addValue("type",taxType).addValue("ps",Date.valueOf(start)).addValue("pe",Date.valueOf(end)).addValue("amount",amount).addValue("status",amount.signum()==0?"PAID":"OPEN").addValue("actor",actor));}
    public TaxLiability taxLiability(long accountId,long liabilityId){return taxLiabilities(accountId).stream().filter(x->x.taxLiabilityId()==liabilityId).findFirst().orElse(null);}
    public void insertTaxPayment(long id,long liabilityId,BigDecimal amount,LocalDate date,String ref,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_TAX_PAYMENT(TAX_PAYMENT_ID,TAX_LIABILITY_ID,PAYMENT_AMOUNT,PAYMENT_DATE,PAYMENT_STATUS_CODE,PAYMENT_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:lid,:amount,:pd,'PAID',:ref,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("lid",liabilityId).addValue("amount",amount).addValue("pd",Date.valueOf(date)).addValue("ref",ref).addValue("actor",actor));}
    public void applyTaxPayment(long liabilityId,BigDecimal amount,String actor){String sql="UPDATE "+schema+".DEPOSIT_TAX_LIABILITY SET PAID_AMOUNT=PAID_AMOUNT+:amount,STATUS_CODE=CASE WHEN PAID_AMOUNT+:amount>=LIABILITY_AMOUNT THEN 'PAID' ELSE 'PARTIALLY_PAID' END,UPDATED_AT=SYSTIMESTAMP,UPDATED_BY=:actor,RECORD_VERSION=RECORD_VERSION+1 WHERE TAX_LIABILITY_ID=:id AND PAID_AMOUNT+:amount<=LIABILITY_AMOUNT";if(jdbc.update(sql,new MapSqlParameterSource().addValue("amount",amount).addValue("actor",actor).addValue("id",liabilityId))!=1)throw new IllegalArgumentException("مبلغ پرداخت از مانده بدهی بیشتر است.");}
    public BigDecimal taxLiabilityAmount(long accountId,String taxType){return taxLiabilities(accountId).stream().filter(x->taxType.equals(x.taxTypeCode())).map(TaxLiability::liabilityAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public BigDecimal taxPaidAmount(long accountId,String taxType){return taxLiabilities(accountId).stream().filter(x->taxType.equals(x.taxTypeCode())).map(TaxLiability::paidAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public void insertTaxReconciliation(long id,LocalDate businessDate,String taxType,BigDecimal book,BigDecimal remitted,BigDecimal external,BigDecimal diff,String status,String resolution,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_TAX_RECONCILIATION(TAX_RECONCILIATION_ID,BUSINESS_DATE,TAX_TYPE_CODE,BOOK_AMOUNT,REMITTED_AMOUNT,EXTERNAL_AMOUNT,DIFFERENCE_AMOUNT,STATUS_CODE,RESOLUTION_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:bd,:type,:book,:remitted,:external,:diff,:status,:resolution,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("bd",Date.valueOf(businessDate)).addValue("type",taxType).addValue("book",book).addValue("remitted",remitted).addValue("external",external).addValue("diff",diff).addValue("status",status).addValue("resolution",resolution).addValue("actor",actor));}
    public int postTaxAdjustment(long adjustmentId,String postingReference,String actor){return jdbc.update("UPDATE "+schema+".DEPOSIT_TAX_ADJUSTMENT J SET J.POSTING_REFERENCE=:ref,J.UPDATED_AT=SYSTIMESTAMP,J.UPDATED_BY=:actor,J.RECORD_VERSION=J.RECORD_VERSION+1 WHERE J.TAX_ADJUSTMENT_ID=:id AND J.POSTING_REFERENCE IS NULL AND EXISTS(SELECT 1 FROM "+schema+".DEPOSIT_OPERATION_APPROVAL_REQUEST A WHERE A.APPROVAL_REQUEST_ID=J.APPROVAL_REQUEST_ID AND A.APPROVAL_STATUS_CODE='APPROVED')",new MapSqlParameterSource().addValue("ref",postingReference).addValue("actor",actor).addValue("id",adjustmentId));}

